import java.io.*;
import java.util.*;

public class Main {
    static class DSU {
        int[] parent;
        int[] sz;

        DSU(int n) {
            parent = new int[n + 1];
            sz = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                sz[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            parent[b] = a;
            sz[a] += sz[b];
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        DSU dsu = new DSU(N);

        int[] head = new int[N + 1];
        Arrays.fill(head, -1);

        int[] to = new int[2 * M];
        int[] next = new int[2 * M];
        int[] deg = new int[N + 1];

        int idx = 0;

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());

            dsu.union(u, v);

            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;
            deg[u]++;

            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
            deg[v]++;
        }

        int chosen = -1;
        int root = -1;

        for (int i = 1; i <= N; i++) {
            int r = dsu.find(i);
            if (deg[i] < dsu.sz[r] - 1) {
                chosen = i;
                root = r;
                break;
            }
        }

        if (chosen == -1) {
            System.out.println("-1");
            return;
        }

        boolean[] marked = new boolean[N + 1];

        for (int e = head[chosen]; e != -1; e = next[e]) {
            marked[to[e]] = true;
        }

        for (int i = 1; i <= N; i++) {
            if (i != chosen && dsu.find(i) == root && !marked[i]) {
                System.out.println(chosen + " " + i);
                return;
            }
        }

        System.out.println("-1");
    }
}
